const cb = $input.first().json.callback_query || $input.first().json;
const data = cb.data || '';
const chatId = String(cb.message?.chat?.id || cb.from?.id || '');
const queryId = String(cb.id || '');

const staticData = $getWorkflowStaticData('global');
const user = (staticData.users || {})[chatId] || { chatId };

const prefixes = ['step0','goal','niche','aud','traffic','stage','ready'];
let prefix = 'unknown';
for (const p of prefixes) {
  if (data.startsWith(p + '_') || data === p) { prefix = p; break; }
}
const value = data.replace(/^(step0_|goal_|niche_|aud_|traffic_|stage_|ready_)/, '');

return [{ json: { ...user, callbackData: data, prefix, value, chatId, queryId } }];

const d = $input.first().json;
const scores = { leads: 3, convert: 3, redesign: 2, curious: 0 };
const staticData = $getWorkflowStaticData('global');
if (staticData.users && staticData.users[d.chatId]) {
  const u = staticData.users[d.chatId];
  u.goal = d.value;
  u.step = 1;
  u.leadScore = (u.leadScore || 0) + (scores[d.value] || 0);
}
return [{ json: d }];

const d = $input.first().json;
const scores = { ecom: 1, b2b: 2, edu: 1, med: 2, horeca: 1, it: 2, other: 1 };
const staticData = $getWorkflowStaticData('global');
if (staticData.users && staticData.users[d.chatId]) {
  const u = staticData.users[d.chatId];
  u.niche = d.value;
  u.step = 2;
  u.leadScore = (u.leadScore || 0) + (scores[d.value] || 1);
}
return [{ json: d }];

