return [{ json: { ...d, reaction: reactions[d.value] || '' } }];

const d = $input.first().json;
const scores = { startup: 1, growth: 3, scale: 4 };
const staticData = $getWorkflowStaticData('global');
if (staticData.users && staticData.users[d.chatId]) {
