const d = $input.first().json;
const scores = { yes: 5, maybe: 3, no: 0 };
const staticData = $getWorkflowStaticData('global');
const user = (staticData.users || {})[d.chatId] || {};

user.readiness = d.value;
user.step = 6;
user.leadScore = (user.leadScore || 0) + (scores[d.value] || 0);

if (user.leadScore >= 18) user.leadType = 'hot';
else if (user.leadScore >= 10) user.leadType = 'warm';
else user.leadType = 'cold';

if (staticData.users) staticData.users[d.chatId] = user;

return [{ json: { ...user, chatId: d.chatId, hasUrl: !!user.projectUrl } }];

const d = $input.first().json;
const text = d.data?.text || d.text || '';
const urlMatch = text.match(/(https?:\/\/[^\s]+)/i);
let projectUrl = urlMatch ? urlMatch[1] : text.trim();
if (projectUrl && !projectUrl.startsWith('http')) projectUrl = 'https://' + projectUrl;

const staticData = $getWorkflowStaticData('global');
const chatId = d.chatId || '';
const user = (staticData.users || {})[chatId] || {};
user.projectUrl = projectUrl;
if (staticData.users) staticData.users[chatId] = user;

return [{ json: { ...user, chatId, projectUrl } }];

const d = $input.first().json;
const staticData = $getWorkflowStaticData('global');
const user = (staticData.users || {})[d.chatId] || d;

const goalMap = { leads: '📈 Больше заявок', convert: '🤔 Не конвертит', redesign: '🎨 Редизайн', curious: '👀 Интересно' };
const nicheMap = { ecom: '🛍 E-commerce', b2b: '💼 Услуги/B2B', edu: '🎓 Обучение', med: '🏥 Медицина', horeca: '🍔 HoReCa', it: '💻 IT/SaaS', other: '🔧 Другое' };
const audMap = { b2c: '👤 B2C', b2b: '🏢 B2B', both: '👤+🏢 Оба', unsure: '🤷 Определяется' };
const trafficMap = { low: '🌱 <500', mid: '📈 500-5к', high: '🚀 5к-50к', mega: '🔥 50к+' };
const stageMap = { startup: '🚀 Запуск', growth: '📊 Рост', scale: '🏢 Масштаб' };
const readyMap = { yes: '✅ Да', maybe: '🤔 Зависит', no: '👀 Смотрит' };
const leadMap = { hot: '🔥 HOT', warm: '🟡 WARM', cold: '🔵 COLD' };
const formMap = { 'Запустить спринт': '🚀 Спринт', 'Обсудить проект': '💬 Обсудить', 'Запустим ваш проект': '🚀 Запуск', 'Заказать аудит': '📋 Аудит', 'Бесплатный аудит': '🎁 Бесплатный', 'Расскажите о вашей идее': '💡 Идея' };

const focusMap = {
  leads: 'Анализ CTA-элементов, форм захвата, воронки конверсии',
  convert: 'Первый экран, ясность УТП, факторы доверия, барьеры конверсии',
  redesign: 'Визуальная современность, UI-паттерны, UX-flow',
  curious: 'Общий обзор всех аспектов с приоритизацией по потенциалу роста'
};

const goalLabel = goalMap[user.goal] || 'N/A';
const nicheLabel = nicheMap[user.niche] || 'N/A';
const audLabel = audMap[user.audience] || 'N/A';
const trafficLabel = trafficMap[user.traffic] || 'N/A';
const stageLabel = stageMap[user.stage] || 'N/A';
const readyLabel = readyMap[user.readiness] || 'N/A';
const leadLabel = leadMap[user.leadType] || '🔵 COLD';
const formLabel = formMap[user.formSource] || user.formSource || 'N/A';
const focusArea = focusMap[user.goal] || focusMap.curious;

const ownerMsg = '🆕 <b>Новая заявка на аудит!</b>\n\n' +
  '👤 ' + (user.name || 'N/A') + '\n' +
  '📱 Chat ID: ' + d.chatId + '\n' +
  '🌐 ' + (user.projectUrl || d.projectUrl || 'N/A') + '\n' +
  '📩 Источник: ' + formLabel + '\n\n' +
  '📋 <b>Профиль:</b>\n' +
  '• Цель: ' + goalLabel + '\n' +
  '• Ниша: ' + nicheLabel + '\n' +
  '• Аудитория: ' + audLabel + '\n' +
  '• Трафик: ' + trafficLabel + '\n' +
  '• Стадия: ' + stageLabel + '\n' +
  '• Готовность: ' + readyLabel + '\n\n' +
  leadLabel + ' Тип лида: ' + (user.leadType || 'cold').toUpperCase() + ' (' + (user.leadScore || 0) + '/24)';

return [{ json: {
  chatId: d.chatId,
  name: user.name || 'N/A',
  projectUrl: user.projectUrl || d.projectUrl || '',
  leadType: user.leadType || 'cold',
  leadScore: user.leadScore || 0,
  ownerMsg,
  goalLabel, nicheLabel, audLabel, trafficLabel, stageLabel, readyLabel, focusArea
} }];

const prev = $('Данные для владельца').first().json;
const r = $input.first().json;
const txt = r.content?.[0]?.text || '';

let auditData;
try {
  auditData = JSON.parse(txt);
} catch(e) {
  const m = txt.match(/\{[\s\S]*\}/);
  auditData = m ? JSON.parse(m[0]) : {
    overall_score: 5.0, total_potential: '+50% CR',
    executive_summary: 'Требуется детальный анализ.',
    scores: [
      {label:'Первый экран',score:5,comment:''},
      {label:'Ясность предложения',score:5,comment:''},
      {label:'CTA и формы',score:5,comment:''},
      {label:'Доверие',score:5,comment:''},
      {label:'Мобильная версия',score:5,comment:''}
    ],
    issues: [],
    quick_wins: ['Проверить скорость загрузки','Добавить чёткий CTA','Добавить отзывы клиентов']
  };
}

while ((auditData.issues || []).length < 5) {
  auditData.issues = auditData.issues || [];
  auditData.issues.push({
    number: auditData.issues.length + 1,
    title: 'Требует анализа',
    problem: 'Необходимо детальное изучение.',
    hypothesis: 'Улучшение повысит конверсию.',
    solution: 'Углублённый анализ.',
    priority: 'средний',
    complexity: 'средняя',
    potential: '+10% CR',
    comment: ''
  });
}
if (!auditData.quick_wins || auditData.quick_wins.length < 3) {
  auditData.quick_wins = auditData.quick_wins || [];
  while (auditData.quick_wins.length < 3) auditData.quick_wins.push('Провести аудит скорости загрузки');
}

return [{ json: {
  chatId: prev.chatId,
  projectUrl: prev.projectUrl,
  name: prev.name,
  leadType: prev.leadType,
  leadScore: prev.leadScore,
  auditData,
  nicheLabel: prev.nicheLabel,
  audLabel: prev.audLabel,
  goalLabel: prev.goalLabel,
  trafficLabel: prev.trafficLabel,
  stageLabel: prev.stageLabel,
  focusArea: prev.focusArea
} }];

