  '<div style="background:#eee;height:20px;border-radius:10px;overflow:hidden"><div style="background:' + gc(s.score) + ';width:' + s.score * 10 + '%;height:100%;border-radius:10px"></div></div>' +
  (s.comment ? '<div style="color:#888;font-size:12px;margin-top:5px">' + s.comment + '</div>' : '') +
  '</div>'
).join('');

