  '<div style="display:flex;gap:20px;margin-top:30px">' +
  '<div style="flex:1;background:#f8f8f8;padding:15px;border-radius:10px;text-align:center"><div style="color:#999;font-size:11px;margin-bottom:5px">Приоритет</div><div style="color:' + pc(i.priority) + ';font-weight:bold">' + i.priority + '</div></div>' +
  '<div style="flex:1;background:#f8f8f8;padding:15px;border-radius:10px;text-align:center"><div style="color:#999;font-size:11px;margin-bottom:5px">Сложность</div><div style="font-weight:bold;color:#333">' + i.complexity + '</div></div>' +
  '<div style="flex:1;background:#f8f8f8;padding:15px;border-radius:10px;text-align:center"><div style="color:#999;font-size:11px;margin-bottom:5px">Потенциал</div><div style="font-weight:bold;color:#4CAF50">' + i.potential + '</div></div>' +
  '</div>' +
  (i.comment ? '<div style="margin-top:20px;padding:15px;background:#FFF3E0;border-radius:10px;color:#E65100;font-size:13px"><b>Комментарий:</b> ' + i.comment + '</div>' : '') +
  '</div>'
).join('');

const qwH = data.quick_wins.map((w, i) =>
  '<div style="display:flex;align-items:center;margin-bottom:15px;padding:15px;background:#E8F5E9;border-radius:10px">' +
  '<div style="min-width:30px;height:30px;background:#4CAF50;color:white;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:bold;margin-right:15px">' + (i+1) + '</div>' +
  '<div style="color:#2E7D32;font-size:15px">' + w + '</div></div>'
