  warm: '<div style="background:#f0f0f0;padding:30px;border-radius:15px;text-align:center"><h2 style="margin:0 0 10px;color:#333">💡 Бесплатная консультация</h2><p style="margin:0;color:#666">30 минут — разберём отчёт вместе и составим план действий</p></div>',
  cold: '<div style="background:#f0f0f0;padding:30px;border-radius:15px;text-align:center"><h2 style="margin:0 0 10px;color:#333">📌 Сохраните отчёт</h2><p style="margin:0;color:#666">Quick wins можно внедрить самостоятельно. Мы рядом, когда будете готовы.</p></div>'
};

